export default "<!doctype html><html lang=\"en\"><head><!-- Google Tag Manager -->\n<script>(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':\nnew Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],\nj=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src=\n'https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);\n})(window,document,'script','dataLayer','GTM-T7GK8MK9');</script>\n<!-- End Google Tag Manager --><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex\"><meta name=\"description\" content=\"AI Visibility Cheat Sheet - your GEO playbook for making your business visible and citable in ChatGPT, Claude, Perplexity, Gemini and Copilot.\"><title>AI Visibility Cheat Sheet | UNIRAB</title><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"alternate icon\" href=\"/favicon.ico\" sizes=\"48x48\"><link rel=\"stylesheet\" href=\"/product.css\"><style>.geo-sheet{\n    /* UNIRAB design system — https://www.unirab.com */\n    --coral:#ff735d; --coral2:#ee5946;\n    --deep:#073c38; --deep2:#062e2c;\n    --mint:#eaf7f2; --soft:#f3f8f6;\n    --bg:#f3f8f6; --card:#ffffff; --ink:#102a2a; --muted:#637170; --line:#dfe8e4;\n    --accent:#ee5946; --accent-soft:#eaf7f2;\n    --ink-on-coral:#1d2423;\n    --green:#073c38; --green-soft:#eaf7f2;\n    --amber:#0d5a54; --amber-soft:#eaf7f2;\n    --red:#ee5946; --red-soft:#ffece9;\n    --violet:#ee5946; --violet-soft:#ffece9;\n    --blue:#073c38; --blue-soft:#eaf7f2;\n    --edge:#a9beb6;\n    --radius:16px; --shadow:0 12px 30px rgba(7,60,56,.08);\n    --coral-glow:0 8px 20px rgba(255,115,93,.23);\n    --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;\n  }.geo-sheet,.geo-sheet *{box-sizing:border-box}.geo-sheet{scroll-behavior:smooth}.geo-sheet{margin:0;background:var(--bg);color:var(--ink);\n    font:15.5px/1.65 Inter,-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    -webkit-text-size-adjust:100%}.geo-sheet .wrap{max-width:1080px;margin:0 auto;padding:0 20px}.geo-sheet header.hero{background:linear-gradient(180deg,var(--deep) 0%,var(--deep2) 100%);padding:54px 0 44px}.geo-sheet .hero h1{font-size:38px;line-height:1.12;margin:0 0 10px;letter-spacing:-.025em;color:#fff}.geo-sheet .hero p.sub{color:#cfe3de;margin:0 0 6px;max-width:70ch}.geo-sheet .hero p.sub b{color:#ff9d8d;font-weight:700}.geo-sheet .hero p.meta{color:#9dbcb5;font-size:12.5px;margin:10px 0 0}.geo-sheet .hero-row{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap}.geo-sheet nav.toc{position:sticky;top:0;z-index:50;background:#fff;\n    border-bottom:1px solid var(--line);margin-top:0}.geo-sheet nav.toc .wrap{display:flex;gap:2px;overflow-x:auto;padding:9px 20px}.geo-sheet nav.toc a{white-space:nowrap;color:var(--muted);text-decoration:none;font-size:13px;font-weight:600;\n    padding:6px 12px;border-radius:9px}.geo-sheet nav.toc a:hover{background:var(--mint);color:var(--deep)}.geo-sheet main{padding:8px 0 40px}.geo-sheet section{margin-top:44px}.geo-sheet section>h2{font-size:24px;margin:0 0 4px;display:flex;align-items:center;gap:10px;\n    letter-spacing:-.02em}.geo-sheet section>h2 .num{display:inline-flex;align-items:center;justify-content:center;flex:none;\n    width:28px;height:28px;border-radius:9px;background:var(--coral);color:var(--ink-on-coral);\n    font-size:13px;font-weight:800;box-shadow:var(--coral-glow)}.geo-sheet section>p.lead{color:var(--muted);margin:2px 0 18px;max-width:78ch}.geo-sheet .card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);\n    padding:18px 20px;box-shadow:var(--shadow)}.geo-sheet .grid{display:grid;gap:14px}.geo-sheet .grid.auto{grid-template-columns:repeat(auto-fit,minmax(240px,1fr))}.geo-sheet .grid.auto2{grid-template-columns:repeat(auto-fit,minmax(320px,1fr))}.geo-sheet .callout{border-left:4px solid var(--deep);background:var(--mint);border-radius:0 12px 12px 0;\n    padding:12px 16px;margin:16px 0}.geo-sheet .callout.good{border-left-color:var(--coral2);background:var(--mint)}.geo-sheet .callout.info{border-left-color:var(--deep);background:var(--mint)}.geo-sheet .callout.bad{border-left-color:var(--coral2);background:var(--red-soft)}.geo-sheet .callout b:first-child{display:block;margin-bottom:2px}.geo-sheet pre{background:var(--soft);border:1px solid var(--line);border-radius:12px;padding:14px 16px;\n    overflow:auto;font-size:12.5px;line-height:1.55;font-family:var(--mono);margin:12px 0}.geo-sheet code{font-family:var(--mono);font-size:.92em;background:var(--mint);color:var(--deep);\n    padding:1px 5px;border-radius:5px}.geo-sheet pre code{background:none;padding:0;color:inherit}.geo-sheet .btn{appearance:none;border:1px solid var(--line);background:#fff;color:var(--deep);\n    font:inherit;font-size:13.5px;font-weight:700;padding:8px 16px;border-radius:10px;cursor:pointer}.geo-sheet .btn:hover{border-color:var(--coral);color:var(--coral2)}.geo-sheet .btn.primary{background:var(--coral);border-color:var(--coral);color:var(--ink-on-coral);\n    font-weight:800;box-shadow:var(--coral-glow)}.geo-sheet .btn.primary:hover{background:var(--coral2);border-color:var(--coral2);color:#fff}.geo-sheet .btn.mini{font-size:12px;padding:5px 12px;border-radius:8px}.geo-sheet header.hero .btn{background:transparent;border:1.5px solid rgba(255,255,255,.4);color:#fff}.geo-sheet header.hero .btn:hover{border-color:var(--coral);color:#fff;background:rgba(255,255,255,.06)}.geo-sheet .badge{display:inline-block;font-size:10.5px;font-weight:700;letter-spacing:.04em;\n    text-transform:uppercase;padding:2px 7px;border-radius:999px}.geo-sheet .badge.citation{background:#ffece9;color:var(--coral2)}.geo-sheet .badge.training{background:var(--mint);color:var(--deep)}.geo-sheet .badge.essential{background:var(--deep);color:#fff}.geo-sheet .badge.optional{background:var(--soft);color:var(--muted)}.geo-sheet /* ---------- diagram ---------- */\n  #diagram{width:100%;height:auto;display:block;background:var(--card);border:1px solid var(--line);\n    border-radius:var(--radius);touch-action:manipulation;box-shadow:var(--shadow)}.geo-sheet #diagram .colhead{font-size:10px;font-weight:700;letter-spacing:.12em;fill:var(--muted)}.geo-sheet #diagram .node{cursor:pointer}.geo-sheet #diagram .node rect{fill:var(--card);stroke:var(--line);stroke-width:1.5;transition:.15s}.geo-sheet #diagram .node text.lbl{font-size:13px;font-weight:600;fill:var(--ink)}.geo-sheet #diagram .node text.sub{font-size:10px;fill:var(--muted)}.geo-sheet #diagram .node:hover rect{stroke:var(--coral)}.geo-sheet #diagram.focusing .node{opacity:.25}.geo-sheet #diagram.focusing .node.on{opacity:1}.geo-sheet #diagram.focusing .node.on rect{stroke:var(--coral2);stroke-width:2;fill:var(--mint)}.geo-sheet #diagram .edge{fill:none;stroke:var(--edge);stroke-width:1.8;transition:.15s}.geo-sheet #diagram.focusing .edge{opacity:.12}.geo-sheet #diagram.focusing .edge.on{opacity:1;stroke:var(--coral2);stroke-width:2.4}.geo-sheet #diagram .legend{font-size:10.5px;fill:var(--muted)}.geo-sheet #diagram-info{background:var(--mint);border:1px solid var(--line);border-left:4px solid var(--deep);\n    border-radius:0 12px 12px 0;margin-top:12px;min-height:64px}.geo-sheet #diagram-info h4{margin:0 0 2px;font-size:14px}.geo-sheet #diagram-info p{margin:0;color:var(--muted);font-size:13.5px}.geo-sheet /* ---------- bot picker ---------- */\n  .botgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(225px,1fr));gap:10px;margin:14px 0}.geo-sheet .bot{border:1.5px solid var(--line);border-radius:11px;padding:10px 12px;cursor:pointer;\n    user-select:none;background:var(--card);position:relative}.geo-sheet .bot .ua{font-family:var(--mono);font-size:12.5px;font-weight:700}.geo-sheet .bot .role{color:var(--muted);font-size:11.5px;margin-top:2px}.geo-sheet .bot .badge{margin-top:6px}.geo-sheet .bot .state{position:absolute;top:10px;right:10px;font-size:11px;font-weight:700}.geo-sheet .bot.allowed{border-color:var(--deep)}.geo-sheet .bot.allowed .state{color:var(--deep)}.geo-sheet .bot.blocked{opacity:.72;background:#fff8f7}.geo-sheet .bot.blocked .ua{text-decoration:line-through}.geo-sheet .bot.blocked .state{color:var(--red)}.geo-sheet .bot-note{font-size:11px;color:var(--muted);margin-top:5px}.geo-sheet /* ---------- builder / forms ---------- */\n  .form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin:12px 0}.geo-sheet label.fld{display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:600;color:var(--muted)}.geo-sheet label.fld input{font:inherit;font-size:13.5px;padding:7px 10px;border-radius:8px;color:var(--ink);\n    border:1px solid var(--line);background:var(--bg)}.geo-sheet label.fld input:focus{outline:2px solid var(--accent);outline-offset:1px;border-color:transparent}.geo-sheet .chiprow{display:flex;gap:6px;flex-wrap:wrap;margin:8px 0 2px}.geo-sheet .chip{border:1.5px solid var(--line);border-radius:999px;padding:4px 12px;font-size:12.5px;\n    font-weight:600;cursor:pointer;background:var(--card);color:var(--muted);user-select:none}.geo-sheet .chip.on{background:var(--mint);border-color:var(--deep);color:var(--deep)}.geo-sheet .chip.assist.on{background:#ffece9;border-color:var(--coral2);color:var(--coral2)}.geo-sheet /* ---------- checklist ---------- */\n  .progress-wrap{display:flex;align-items:center;gap:12px;margin:14px 0 18px}.geo-sheet .progress-bar{flex:1;height:10px;border-radius:999px;background:var(--line);overflow:hidden}.geo-sheet .progress-fill{height:100%;width:0;background:linear-gradient(90deg,var(--coral),var(--coral2));\n    border-radius:999px;transition:width .3s}.geo-sheet #progress-label{font-weight:700;font-size:14px;min-width:52px;text-align:right}.geo-sheet ul.checklist{list-style:none;margin:0;padding:0;display:grid;gap:8px;\n    grid-template-columns:repeat(auto-fit,minmax(300px,1fr))}.geo-sheet ul.checklist li{display:flex;gap:10px;align-items:flex-start;background:var(--card);\n    border:1px solid var(--line);border-radius:11px;padding:11px 14px;cursor:pointer;user-select:none}.geo-sheet ul.checklist li .box{flex:none;width:20px;height:20px;border-radius:6px;border:2px solid var(--line);\n    margin-top:1px;display:grid;place-items:center;font-size:13px;color:transparent}.geo-sheet ul.checklist li.done{opacity:.62}.geo-sheet ul.checklist li.done .box{background:var(--green);border-color:var(--green);color:#fff}.geo-sheet ul.checklist li.done .txt{text-decoration:line-through}.geo-sheet /* ---------- prompt tracker ---------- */\n  .pt-entry{background:var(--card);border:1px solid var(--line);border-radius:11px;\n    padding:10px 14px;margin-top:8px;display:flex;justify-content:space-between;gap:12px;align-items:center}.geo-sheet .pt-entry .q{font-weight:600;font-size:14px}.geo-sheet .pt-entry .d{color:var(--muted);font-size:11.5px}.geo-sheet .pt-entry .badges{display:flex;gap:5px;flex-wrap:wrap;margin-top:4px}.geo-sheet .pt-b{font-size:10.5px;font-weight:700;padding:2px 8px;border-radius:999px;\n    border:1.5px solid var(--line);color:var(--muted)}.geo-sheet .pt-b.hit{background:var(--green-soft);border-color:var(--green);color:var(--green)}.geo-sheet .pt-del{background:none;border:none;color:var(--muted);font-size:16px;cursor:pointer;padding:2px 6px}.geo-sheet .pt-del:hover{color:var(--red)}.geo-sheet #pt-empty{color:var(--muted);font-size:13px;margin-top:8px}.geo-sheet ul.tight{margin:8px 0;padding-left:20px}.geo-sheet ul.tight li{margin:5px 0}.geo-sheet .mini-cards .card h4{margin:0 0 4px;font-size:14.5px}.geo-sheet .mini-cards .card p{margin:0;color:var(--muted);font-size:13px}.geo-sheet footer{border-top:1px solid var(--line);margin-top:48px;padding:20px 0 40px;color:var(--muted);font-size:13px}.geo-sheet footer a{color:var(--accent)}.geo-sheet .dont .card{border-left:4px solid var(--red)}.geo-sheet .dont .card h4{margin:0 0 3px;font-size:14px}.geo-sheet .dont .card p{margin:0;color:var(--muted);font-size:13px}\n  @media print{.geo-sheet nav.toc{display:none}.geo-sheet{background:#fff}.geo-sheet header.hero{background:#fff}.geo-sheet header.hero h1{color:var(--ink)}.geo-sheet header.hero p.sub,.geo-sheet header.hero p.meta{color:var(--muted)}.geo-sheet header.hero p.sub b{color:var(--coral2)}.geo-sheet .card,.geo-sheet pre{break-inside:avoid}\n  }\n</style></head><body><!-- Google Tag Manager (noscript) -->\n<noscript><iframe src=\"https://www.googletagmanager.com/ns.html?id=GTM-T7GK8MK9\"\nheight=\"0\" width=\"0\" style=\"display:none;visibility:hidden\"></iframe></noscript>\n<!-- End Google Tag Manager (noscript) -->\n<header class=\"product-header\"><button class=\"menu\" aria-label=\"Open navigation\" aria-expanded=\"false\"><span></span><span></span></button><nav class=\"product-nav\" aria-label=\"Primary\"><button class=\"nav-close\" type=\"button\" aria-label=\"Close navigation\">×</button><a href=\"/#included\">About</a><a href=\"/#pricing\">Pricing</a><a href=\"/#how\">How It Works</a><a href=\"/case-studies\">Case Studies</a><a href=\"/#faq\">Support</a><a href=\"/login\">Customer Login</a></nav><a class=\"brand\" href=\"/\" aria-label=\"UNIRAB home\"><span>UNI</span><b>RAB</b><i></i></a></header>\n<div class=\"geo-sheet\">\n<header class=\"hero\">\n  <div class=\"wrap hero-row\">\n    <div>\n      <h1>GEO Cheat Sheet</h1>\n      <p class=\"sub\"><b>G</b>enerative <b>E</b>ngine <b>O</b>ptimization — making your website, Google&nbsp;Business&nbsp;Profile and Facebook page visible &amp; citable for ChatGPT, Claude, Perplexity, Gemini and Copilot.</p>\n      <p class=\"meta\">Single self-contained file · works offline · tracker &amp; checklist data stays in this browser only</p>\n    </div>\n    <button class=\"btn\" onclick=\"window.print()\">Print / Save as PDF</button>\n  </div>\n</header>\n\n<nav class=\"toc\"><div class=\"wrap\">\n  <a href=\"#how\">How it works</a>\n  <a href=\"#crawlers\">Crawlers</a>\n  <a href=\"#content\">Content</a>\n  <a href=\"#schema\">Schema builder</a>\n  <a href=\"#infra\">Feeds &amp; files</a>\n  <a href=\"#local\">Local &amp; social</a>\n  <a href=\"#mentions\">Mentions</a>\n  <a href=\"#measure\">Measure</a>\n  <a href=\"#donts\">Don'ts</a>\n  <a href=\"#quickstart\">Checklist</a>\n</div></nav>\n\n<main class=\"wrap\">\n\n<!-- ============ 0. DIAGRAM ============ -->\n<section id=\"how\">\n  <h2><span class=\"num\">0</span> How AI assistants find you</h2>\n  <p class=\"lead\">Hover or tap any node in the diagram to see why it matters and what to do about it. Tap empty space to unpin.</p>\n  <svg id=\"diagram\" viewBox=\"0 0 960 470\" role=\"img\" aria-label=\"Flow diagram: a user question goes to AI assistants, which consult indexes, live fetches and community sources, which draw from your website, Google Business Profile, Facebook page and third-party mentions.\"></svg>\n  <div id=\"diagram-info\">\n    <h4>👆 Hover or tap a node</h4>\n    <p>The diagram shows the path from a user's question to a citation of your business. Highlight a node to trace its connections.</p>\n  </div>\n  <div class=\"callout info\" style=\"margin-top:16px\">\n    <b>The two-part game</b>\n    Classic SEO is still the foundation — assistants work off the Google &amp; Bing indexes. On top of that: (1)&nbsp;be <b>extractable</b> — your site readable by machines, and (2)&nbsp;be <b>mentioned</b> — present in the third-party sources (Reddit, reviews, directories) that assistants cite disproportionately.\n  </div>\n</section>\n\n<!-- ============ 1. CRAWLERS ============ -->\n<section id=\"crawlers\">\n  <h2><span class=\"num\">1</span> Let the AI crawlers in</h2>\n  <p class=\"lead\">Toggle the bots below — the <code>robots.txt</code> updates live. Defaults reflect what a business that wants AI citations should use. \"Citation\" bots get you into answers; \"training\" bots shape future models.</p>\n\n  <div class=\"card\">\n    <div class=\"botgrid\" id=\"botgrid\"></div>\n    <div style=\"display:flex;align-items:center;gap:12px;flex-wrap:wrap\">\n      <span id=\"bot-summary\" style=\"font-size:13px;color:var(--muted)\"></span>\n      <span style=\"flex:1\"></span>\n      <button class=\"btn primary mini copy-btn\" data-copy=\"robots-out\">Copy robots.txt</button>\n    </div>\n    <pre id=\"robots-out\"><code></code></pre>\n  </div>\n\n  <div class=\"callout\">\n    <b>⚠️ robots.txt is necessary but not sufficient</b>\n    Cloudflare's \"Bot Fight Mode\" and similar WAF features block AI crawlers regardless of robots.txt. Verify in your firewall settings, or test directly:\n    <pre style=\"margin:8px 0 0\"><code>curl -A \"OAI-SearchBot/1.0\" -I https://yoursite.com   # expect HTTP/2 200</code></pre>\n    Also confirm there are no <code>noindex</code> meta tags and no JS-only rendering (see section&nbsp;2).\n  </div>\n</section>\n\n<!-- ============ 2. CONTENT ============ -->\n<section id=\"content\">\n  <h2><span class=\"num\">2</span> Make your content machine-extractable</h2>\n  <p class=\"lead\">Assistants parse raw HTML and lift passages. Write to be lifted.</p>\n  <div class=\"grid auto mini-cards\">\n    <div class=\"card\"><h4>🏗️ Server-side rendered HTML</h4><p>If the text isn't in the raw HTML, most bots never see it. Test: <code>curl https://yoursite.com | grep \"key phrase\"</code>. Client-side-only SPAs are invisible.</p></div>\n    <div class=\"card\"><h4>🎯 Answer-first sentences</h4><p>First sentence under each heading should be a self-contained, quotable answer: \"Standard delivery takes 2–3 working days.\" — not \"Here at our company we believe…\".</p></div>\n    <div class=\"card\"><h4>❓ Headings phrased as questions</h4><p>\"Do you deliver outside Austin?\", \"How much does X cost?\" — these mirror how people prompt assistants.</p></div>\n    <div class=\"card\"><h4>📋 A real FAQ page</h4><p>10–20 genuine customer questions with direct answers. Prime harvesting ground for citations.</p></div>\n    <div class=\"card\"><h4>🔢 Facts, numbers, dates, prices</h4><p>Attach dates (\"As of 2026…\"). Models prefer citing concrete, sourced statements over vague marketing copy.</p></div>\n    <div class=\"card\"><h4>📊 Tables &amp; lists</h4><p>For anything enumerable — prices, hours, locations, comparisons. The easiest format for a model to reproduce accurately.</p></div>\n    <div class=\"card\"><h4>🧭 One name everywhere (NAP)</h4><p>Identical business name, address and phone on the site, Google profile, Facebook and directories. Consistency = the entity resolves to <em>you</em>.</p></div>\n    <div class=\"card\"><h4>⚡ Fast &amp; unfussy pages</h4><p>Bots don't click cookie banners or close popups — content behind interstitials effectively doesn't exist. One <code>&lt;h1&gt;</code>, logical headings, descriptive titles, image alt text.</p></div>\n  </div>\n</section>\n\n<!-- ============ 3. SCHEMA BUILDER ============ -->\n<section id=\"schema\">\n  <h2><span class=\"num\">3</span> Structured data builder (JSON-LD)</h2>\n  <p class=\"lead\">The machine-readable business card that ties your website, Google profile and Facebook page into one entity. Fill the form — the snippet updates live. Paste it into your homepage's <code>&lt;head&gt;</code>, then validate in Google's <b>Rich Results Test</b>.</p>\n  <div class=\"card\">\n    <div class=\"form-grid\">\n      <label class=\"fld\">Business name *<input id=\"f-name\" placeholder=\"Acme Bakery\"></label>\n      <label class=\"fld\">Website URL *<input id=\"f-url\" placeholder=\"https://yoursite.com\"></label>\n      <label class=\"fld\">Phone<input id=\"f-phone\" placeholder=\"+1 512 555 0143\"></label>\n      <label class=\"fld\">Price range<input id=\"f-price\" placeholder=\"$$\"></label>\n      <label class=\"fld\">Street<input id=\"f-street\" placeholder=\"123 Main St\"></label>\n      <label class=\"fld\">City<input id=\"f-city\" placeholder=\"Austin\"></label>\n      <label class=\"fld\">Postal code<input id=\"f-postal\" placeholder=\"78701\"></label>\n      <label class=\"fld\">Country code<input id=\"f-country\" placeholder=\"US\"></label>\n      <label class=\"fld\">Google Business Profile link<input id=\"f-gbp\" placeholder=\"https://maps.google.com/…\"></label>\n      <label class=\"fld\">Facebook page<input id=\"f-fb\" placeholder=\"https://facebook.com/yourpage\"></label>\n      <label class=\"fld\">Instagram<input id=\"f-ig\" placeholder=\"https://instagram.com/yourprofile\"></label>\n      <label class=\"fld\">Image URL<input id=\"f-img\" placeholder=\"https://yoursite.com/og-image.jpg\"></label>\n    </div>\n    <div style=\"font-size:12px;font-weight:700;color:var(--muted);margin-top:6px\">OPENING HOURS</div>\n    <div class=\"chiprow\" id=\"schema-days\"></div>\n    <div class=\"form-grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(140px,1fr))\">\n      <label class=\"fld\">Opens<input id=\"f-opens\" type=\"time\" value=\"09:00\"></label>\n      <label class=\"fld\">Closes<input id=\"f-closes\" type=\"time\" value=\"19:00\"></label>\n    </div>\n    <div id=\"schema-warn\" style=\"display:none;color:var(--amber);font-size:13px;font-weight:600;margin-bottom:6px\"></div>\n    <div style=\"display:flex;justify-content:flex-end\"><button class=\"btn primary mini copy-btn\" data-copy=\"schema-out\">Copy JSON-LD</button></div>\n    <pre id=\"schema-out\"><code></code></pre>\n  </div>\n  <div class=\"callout good\">\n    <b>The <code>sameAs</code> array is the glue</b>\n    It's what tells every search engine and assistant that the website, the Google profile and the Facebook page are the same entity. Don't skip it. Use <code>Product</code>+<code>Offer</code> on product pages, <code>FAQPage</code> on the FAQ, and <code>AggregateRating</code> only if the reviews are real and visible on-page.\n  </div>\n</section>\n\n<!-- ============ 4. FEEDS & FILES ============ -->\n<section id=\"infra\">\n  <h2><span class=\"num\">4</span> Feeds, sitemaps &amp; llms.txt</h2>\n  <div class=\"grid auto2 mini-cards\">\n    <div class=\"card\"><h4>🗺️ sitemap.xml</h4><p>Auto-generated and current. Submit in Google Search Console <em>and</em> Bing Webmaster Tools.</p></div>\n    <div class=\"card\"><h4>🔔 Bing + IndexNow</h4><p>ChatGPT search leans on Bing — and most competitors neglect it. Submit to Bing Webmaster Tools and ping updates via IndexNow.</p></div>\n    <div class=\"card\"><h4>📰 RSS / Atom feed</h4><p>Helps crawlers and aggregators discover fresh content.</p></div>\n    <div class=\"card\"><h4>📄 llms.txt — honest take</h4><p>A Markdown overview of your site at <code>/llms.txt</code>. Cheap and harmless, but <b>no major assistant has confirmed reading third-party ones</b> — empirical tests mostly show they ignore it. Add it in 15 minutes; expect nothing.</p></div>\n    <div class=\"card\"><h4>🧷 Clean URLs &amp; canonicals</h4><p>Canonical tags to avoid duplicates, OpenGraph tags (<code>og:title</code>, <code>og:image</code>) for tidy citations.</p></div>\n    <div class=\"card\"><h4>🔒 Don't over-block</h4><p>Blocking <code>Google-Extended</code> only opts you out of Gemini <em>training</em> — it has no effect on your Google ranking or AI Overviews either way.</p></div>\n  </div>\n</section>\n\n<!-- ============ 5. LOCAL & SOCIAL ============ -->\n<section id=\"local\">\n  <h2><span class=\"num\">5</span> Google profile &amp; Facebook page</h2>\n  <div class=\"grid auto2\">\n    <div class=\"card\">\n      <h4 style=\"margin-top:0\">📍 Google Business Profile — the local AI food source</h4>\n      <p style=\"color:var(--muted);font-size:13.5px\">For \"best X near me / in [city]\" questions, assistants pull heavily from Google Maps data and reviews — the profile is often quoted nearly verbatim.</p>\n      <ul class=\"tight\" style=\"font-size:13.5px\">\n        <li><b>Fill every field:</b> precise categories, service area, holiday hours, attributes, booking links, products.</li>\n        <li><b>Exact business name, no keyword stuffing</b> — \"Name — Keyword City\" as the profile name risks suspension; keywords go in the description.</li>\n        <li><b>Seed the Q&amp;A:</b> write the 5–10 questions customers actually ask and answer them as the owner — assistants quote these directly.</li>\n        <li><b>Reviews:</b> ask happy customers (in person, receipts, WhatsApp) and reply to every one, naturally restating facts (\"…yes, we're open Mon–Sat 10:00–20:00\"). Never fabricate.</li>\n        <li><b>Weekly posts + photos</b> with descriptive filenames (<code>store-window-austin.jpg</code>, not <code>IMG_4471.jpg</code>).</li>\n        <li><b>Repeat the essentials on Bing Places</b> — ChatGPT's local answers lean on Bing.</li>\n      </ul>\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-top:0\">📘 Facebook page — reality check</h4>\n      <div class=\"callout bad\" style=\"margin-top:10px\">\n        <b>Login-walled</b>\n        LLMs essentially cannot read your posts. The page matters as an <em>entity signal and citation</em>, not as a content source.\n      </div>\n      <ul class=\"tight\" style=\"font-size:13.5px\">\n        <li>Page must be <b>public</b> and complete: About with NAP + website link, correct category, verified if eligible.</li>\n        <li>Maintain it for humans — and because it ranks in Google/Bing for your brand name, which assistants then see.</li>\n        <li><b>Any fact that matters</b> (hours, prices, FAQ) must also live on the crawlable site and Google profile. Facebook is the billboard, not the database.</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ============ 7. MENTIONS ============ -->\n<section id=\"mentions\">\n  <h2><span class=\"num\">6</span> Get mentioned where LLMs already look</h2>\n  <p class=\"lead\">Half the game. Assistants trust and cite these disproportionately.</p>\n  <div class=\"grid auto mini-cards\">\n    <div class=\"card\"><h4>👾 Reddit</h4><p>Disproportionately cited. Participate honestly in local/niche subreddits — astroturfing gets called out publicly and backfires.</p></div>\n    <div class=\"card\"><h4>⭐ Review platforms</h4><p>Google Maps, Yelp, TripAdvisor, Trustpilot — and for B2B: G2, Capterra, Clutch.</p></div>\n    <div class=\"card\"><h4>📚 Directories</h4><p>Chambers of commerce, industry directories, municipality listings — consistent NAP everywhere.</p></div>\n    <div class=\"card\"><h4>🧠 Wikidata</h4><p>A structured item for your business (official site + <code>sameAs</code>) strengthens entity recognition. Full Wikipedia articles require real notability — don't force it.</p></div>\n    <div class=\"card\"><h4>📰 Local media / digital PR</h4><p>One real local-news mention beats a hundred spam directories. Publish citable material — \"average prices in [city] 2026\", a small survey, a guide.</p></div>\n  </div>\n</section>\n\n<!-- ============ 8. MEASURE ============ -->\n<section id=\"measure\">\n  <h2><span class=\"num\">7</span> Measure it</h2>\n  <p class=\"lead\">Three checks: are you crawled, are you referred traffic, are you in the answers?</p>\n  <div class=\"grid auto2 mini-cards\">\n    <div class=\"card\"><h4>🤖 Are you even crawled?</h4><p>Filter server logs / analytics for user agents <code>GPTBot</code>, <code>OAI-SearchBot</code>, <code>ClaudeBot</code>, <code>PerplexityBot</code>. Zero hits → revisit section 1.</p></div>\n    <div class=\"card\"><h4>🔗 AI referral traffic</h4><p>Segment referrers <code>chatgpt.com</code>, <code>perplexity.ai</code>, <code>copilot.microsoft.com</code>, <code>gemini.google.com</code>. Tag links you paste into chats with <code>?utm_source=chatgpt</code>.</p></div>\n  </div>\n  <div class=\"card\" style=\"margin-top:14px\">\n    <h4 style=\"margin:0 0 4px\">🗓️ Prompt tracker — log what the assistants say</h4>\n    <p style=\"color:var(--muted);font-size:13px;margin:0 0 10px\">Once a month, ask ChatGPT, Claude, Perplexity and Gemini your money queries (\"best [category] in [city]\", your brand name), then record which ones mentioned you. Answers fluctuate — watch the trend, not any single answer. Saved locally in this browser.</p>\n    <div style=\"display:flex;gap:10px;flex-wrap:wrap;align-items:center\">\n      <input id=\"pt-query\" placeholder=\"e.g. best bakery in Austin\"\n        style=\"flex:1;min-width:220px;font:inherit;font-size:13.5px;padding:8px 12px;border-radius:9px;border:1px solid var(--line);background:var(--bg);color:var(--ink)\">\n      <button class=\"btn primary\" id=\"pt-save\">Log result</button>\n    </div>\n    <div class=\"chiprow\" id=\"pt-chips\"></div>\n    <div id=\"pt-list\"></div>\n    <div id=\"pt-empty\">No entries yet — log your first baseline above.</div>\n  </div>\n</section>\n\n<!-- ============ 9. DON'TS ============ -->\n<section id=\"donts\" class=\"dont\">\n  <h2><span class=\"num\">8</span> Don'ts</h2>\n  <div class=\"grid auto\">\n    <div class=\"card\"><h4>❌ Fake reviews / review gating</h4><p>Platform detection + suspension + reputational damage.</p></div>\n    <div class=\"card\"><h4>❌ Hidden text / LLM keyword stuffing</h4><p>Models extract meaning, not keyword density. Does nothing, can hurt.</p></div>\n    <div class=\"card\"><h4>❌ Keyword-stuffed business names</h4><p>On the Google profile it's a suspension risk.</p></div>\n    <div class=\"card\"><h4>❌ \"Guaranteed ChatGPT citations\" vendors</h4><p>Nobody can guarantee it. It's a probabilistic game.</p></div>\n    <div class=\"card\"><h4>❌ Blocking Google-Extended for ranking reasons</h4><p>It only controls Gemini training, not your Google ranking.</p></div>\n    <div class=\"card\"><h4>❌ Expecting a switch to flip</h4><p>Answers change weekly. GEO is compounding hygiene — crawlability + facts + mentions — closer to PR than to paid ads.</p></div>\n  </div>\n</section>\n\n<!-- ============ 10. QUICKSTART ============ -->\n<section id=\"quickstart\">\n  <h2><span class=\"num\">9</span> One-hour quick start</h2>\n  <p class=\"lead\">Click items off as you go — progress is saved in this browser.</p>\n  <div class=\"progress-wrap\">\n    <div class=\"progress-bar\"><div class=\"progress-fill\" id=\"progress-fill\"></div></div>\n    <span id=\"progress-label\">0%</span>\n    <button class=\"btn mini\" id=\"progress-reset\">Reset</button>\n  </div>\n  <ul class=\"checklist\" id=\"quicklist\"></ul>\n</section>\n\n</main>\n\n<footer><div class=\"wrap\">\n  <b>References:</b>\n  <a href=\"https://developers.openai.com/api/docs/bots\">OpenAI crawler docs</a> ·\n  <a href=\"https://support.anthropic.com/en/articles/8896518\">Anthropic crawler info</a> ·\n  <a href=\"https://github.com/ai-robots-txt/ai.robots.txt\">ai.robots.txt community list</a> ·\n  <a href=\"https://llmstxt.org\">llms.txt spec (unadopted by major assistants as of late 2026)</a> ·\n  <a href=\"https://okara.ai/blog/robots-txt-for-ai-crawlers\">okara.ai crawler guide</a> ·\n  <a href=\"https://geotoolbox.ai/blog/ai-crawlers\">geotoolbox crawler list</a>\n  <br><span style=\"font-size:12px\">Companion markdown version: <code>ai-visibility-cheat-sheet.md</code></span>\n</div></footer>\n</div>\n<footer class=\"site-footer\"><div class=\"footer-grid\"><div><a class=\"brand footer-brand\" href=\"/\"><span>UNI</span><b>RAB</b><i></i></a><p>AI visibility for local business.<br>Built with care, measured monthly.</p></div><div><h3>Company</h3><a href=\"/\">Home</a><a href=\"/#included\">About Us</a><a href=\"/case-studies\">Case Studies</a><a href=\"/#how\">How It Works</a><a href=\"/#cheat-sheet\">AI Cheat Sheet</a><a href=\"/#reviews\">Reviews</a></div><div><h3>Resources</h3><a href=\"/contact\">Contact Us</a><a href=\"/policies/privacy-policy\">Privacy Policy</a><a href=\"/policies/terms-of-service\">Terms of Service</a><a href=\"/policies/refund-policy\">Refund Policy</a><a href=\"/policies/subscription-policy\">Cancellation Policy</a></div><div><h3>Partners</h3><a href=\"/reseller-program\">Reseller Program</a><a href=\"/login\">Reseller Dashboard</a></div></div><p class=\"copyright\">© 2026 UNIRAB. All rights reserved. · <a href=\"/policies/privacy-policy\">Privacy Policy</a> · <a href=\"/policies/terms-of-service\">Terms of Service</a></p></footer>\n<script>const menu=document.querySelector('.menu'),nav=document.querySelector('.product-nav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav?.addEventListener('click',e=>{if(e.target.matches('a')||e.target.closest('.nav-close')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(nav&&nav.classList.contains('open')&&!nav.contains(e.target)&&!menu.contains(e.target)){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});</script>\n<script>\n'use strict';\n/* ================= utilities ================= */\nconst $ = (s, r) => (r || document).querySelector(s);\nconst $$ = (s, r) => Array.from((r || document).querySelectorAll(s));\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction store(key, val){\n  try{\n    if (val === undefined){ const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : null; }\n    localStorage.setItem(key, JSON.stringify(val));\n  }catch(e){ return null; }\n}\nasync function copyText(text, btn){\n  try{ await navigator.clipboard.writeText(text); }\n  catch(e){\n    const ta = document.createElement('textarea');\n    ta.value = text; document.body.appendChild(ta); ta.select();\n    try{ document.execCommand('copy'); }catch(_){}\n    ta.remove();\n  }\n  const old = btn.textContent;\n  btn.textContent = 'Copied ✓';\n  setTimeout(() => { btn.textContent = old; }, 1400);\n}\ndocument.addEventListener('click', e => {\n  const btn = e.target.closest('.copy-btn');\n  if (!btn) return;\n  const el = document.getElementById(btn.dataset.copy);\n  copyText(el ? el.textContent : '', btn);\n});\nwindow.addEventListener('beforeprint', () => $$('details').forEach(d => d.open = true));\n\n/* ================= 1. diagram ================= */\n(function buildDiagram(){\n  const svg = $('#diagram');\n  const NS = 'http://www.w3.org/2000/svg';\n  const W = 150, H = 46;\n  const cols = { user:85, asst:300, src:545, you:830 };\n  const nodes = [\n    {id:'user',   c:'user', x:cols.user, y:234, l:'👤 Someone asks', s:'a real question', info:['Someone asks an AI','Queries like \"best X in [city]\" or \"who sells Y\". Your entire job in GEO is to be the answer these prompts surface — on your site and in the sources the assistant trusts.']},\n    {id:'chatgpt',c:'asst', x:cols.asst, y:66,  l:'ChatGPT', s:'OpenAI · search mode', info:['ChatGPT (search mode)','Pulls web results (Bing-powered) and fetches pages live. Being indexed by Bing and crawlable is what makes you citable.']},\n    {id:'claude', c:'asst', x:cols.asst, y:150, l:'Claude', s:'Anthropic · web search', info:['Claude (web search on)','Runs a search, then fetches your pages directly. Clean, server-rendered HTML is what it actually reads.']},\n    {id:'pplx',   c:'asst', x:cols.asst, y:234, l:'Perplexity', s:'own index + live crawl', info:['Perplexity','Keeps its own index and cites Reddit, reviews and directories disproportionately — third-party presence matters most here.']},\n    {id:'gemini', c:'asst', x:cols.asst, y:318, l:'Gemini / Overviews', s:'Google', info:['Gemini & Google AI Overviews','Draw from the Google index. Classic SEO is the lever. (Google-Extended only controls model training, not these answers.)']},\n    {id:'copilot',c:'asst', x:cols.asst, y:402, l:'Copilot', s:'Microsoft · Bing', info:['Copilot','Answers from the Bing index. Most competitors ignore Bing Webmaster Tools — submit and use IndexNow.']},\n    {id:'bing',   c:'src',  x:cols.src, y:90,  l:'Bing index', s:'feeds ChatGPT + Copilot', info:['The Bing index','Feeds ChatGPT search and Copilot. Submit via Bing Webmaster Tools, keep the sitemap fresh, use IndexNow for instant updates.']},\n    {id:'google', c:'src',  x:cols.src, y:190, l:'Google index', s:'feeds Gemini', info:['The Google index','Feeds Gemini and AI Overviews. Google Search Console, sitemap, and classic on-page SEO are still the foundation.']},\n    {id:'live',   c:'src',  x:cols.src, y:290, l:'Live page fetch', s:'at answer time', info:['Live fetch / crawl','Assistants fetch pages when answering. Content must be in the raw HTML (curl test), fast, and not hidden behind popups or cookie walls.']},\n    {id:'community',c:'src',x:cols.src, y:390, l:'Reddit · reviews', s:'directories · Wikipedia', info:['Trusted third parties','Assistants cite Reddit, review sites, directories and Wikipedia disproportionately. Real mentions here often outweigh anything on your own site.']},\n    {id:'site',   c:'you',  x:cols.you, y:90,  l:'🌐 Your website', s:'SSR · schema · FAQ', info:['Your website','Server-rendered HTML, answer-first sentences, question-style headings, an FAQ page, JSON-LD schema, consistent NAP. This is the asset you fully control.']},\n    {id:'gbp',    c:'you',  x:cols.you, y:190, l:'📍 Google profile', s:'local data + reviews', info:['Google Business Profile','Assistants quote GBP categories, hours, Q&A and reviews nearly verbatim for local queries. Fill every field, seed Q&As, collect real reviews.']},\n    {id:'fb',     c:'you',  x:cols.you, y:290, l:'📘 Facebook page', s:'entity signal only', info:['Facebook page — login-walled','LLMs cannot read your posts. The page is an entity/citation signal only; every important fact must also live on the site and GBP.']},\n    {id:'third',  c:'you',  x:cols.you, y:390, l:'🔗 Mentions elsewhere', s:'press · directories · Wikidata', info:['Third-party mentions','Directories, local press, Wikidata, review platforms — consistent NAP everywhere. One real news mention beats 100 spam directories.']},\n  ];\n  const edges = [\n    ['user','chatgpt'],['user','claude'],['user','pplx'],['user','gemini'],['user','copilot'],\n    ['chatgpt','bing'],['chatgpt','live'],\n    ['claude','live'],\n    ['pplx','live'],\n    ['gemini','google'],\n    ['copilot','bing'],\n    ['chatgpt','community',{thin:1}],['pplx','community',{thin:1}],\n    ['bing','site'],['google','site'],['live','site'],\n    ['google','gbp'],['live','gbp'],\n    ['community','gbp'],['community','third'],['live','third'],\n    ['community','fb',{dash:1}],['live','fb',{dash:1}],\n  ];\n  const byId = {}; nodes.forEach(n => byId[n.id] = n);\n\n  // defs: arrow markers\n  const defs = document.createElementNS(NS,'defs');\n  const mk = (id, fill) => {\n    const m = document.createElementNS(NS,'marker');\n    m.setAttribute('id',id); m.setAttribute('viewBox','0 0 10 10');\n    m.setAttribute('refX',9); m.setAttribute('refY',5);\n    m.setAttribute('markerWidth',7); m.setAttribute('markerHeight',7);\n    m.setAttribute('orient','auto-start-reverse');\n    const p = document.createElementNS(NS,'path');\n    p.setAttribute('d','M 0 1 L 9 5 L 0 9 z'); p.setAttribute('fill',fill);\n    m.appendChild(p); defs.appendChild(m);\n  };\n  mk('arr','#a9beb6'); mk('arr-on','#ee5946');\n  svg.appendChild(defs);\n\n  // column headers\n  [['QUESTION',cols.user],['ASSISTANTS',cols.asst],['WHERE THEY LOOK',cols.src],['YOUR ASSETS',cols.you]]\n  .forEach(([t,x]) => {\n    const el = document.createElementNS(NS,'text');\n    el.setAttribute('class','colhead'); el.setAttribute('x',x); el.setAttribute('y',26);\n    el.setAttribute('text-anchor','middle'); el.textContent = t;\n    svg.appendChild(el);\n  });\n\n  // edges (endpoints fanned out so stacked arrowheads don't overlap)\n  const edgeEls = {};\n  const outCount = {}, inCount = {}, outIdx = {}, inIdx = {};\n  edges.forEach(([f,t]) => { outCount[f] = (outCount[f]||0)+1; inCount[t] = (inCount[t]||0)+1; outIdx[f] = 0; inIdx[t] = 0; });\n  const spread = (count, i) => (i - (count-1)/2) * 15;\n  edges.forEach(([from,to,opt]) => {\n    const a = byId[from], b = byId[to];\n    const x1 = a.x + W/2, x2 = b.x - W/2;\n    const y1 = a.y + spread(outCount[from], outIdx[from]++);\n    const y2 = b.y + spread(inCount[to], inIdx[to]++);\n    const dx = Math.max(40, (x2 - x1) * 0.45);\n    const p = document.createElementNS(NS,'path');\n    p.setAttribute('d',`M ${x1} ${y1} C ${x1+dx} ${y1}, ${x2-dx} ${y2}, ${x2-2} ${y2}`);\n    p.setAttribute('class','edge');\n    p.setAttribute('marker-end','url(#arr)');\n    if (opt && opt.dash) p.setAttribute('stroke-dasharray','3 5');\n    if (opt && opt.thin){ p.setAttribute('stroke-width','1.1'); p.setAttribute('opacity','.55'); }\n    svg.appendChild(p);\n    edgeEls[from+'-'+to] = p;\n  });\n\n  // nodes\n  const nodeEls = {};\n  nodes.forEach(n => {\n    const g = document.createElementNS(NS,'g');\n    g.setAttribute('class','node'); g.dataset.id = n.id;\n    const r = document.createElementNS(NS,'rect');\n    r.setAttribute('x',n.x - W/2); r.setAttribute('y',n.y - H/2);\n    r.setAttribute('width',W); r.setAttribute('height',H); r.setAttribute('rx',11);\n    const t1 = document.createElementNS(NS,'text');\n    t1.setAttribute('class','lbl'); t1.setAttribute('x',n.x); t1.setAttribute('y',n.y - 2);\n    t1.setAttribute('text-anchor','middle'); t1.textContent = n.l;\n    const t2 = document.createElementNS(NS,'text');\n    t2.setAttribute('class','sub'); t2.setAttribute('x',n.x); t2.setAttribute('y',n.y + 14);\n    t2.setAttribute('text-anchor','middle'); t2.textContent = n.s;\n    g.append(r,t1,t2);\n    svg.appendChild(g);\n    nodeEls[n.id] = g;\n  });\n\n  // legend\n  const lg = document.createElementNS(NS,'text');\n  lg.setAttribute('class','legend'); lg.setAttribute('x',16); lg.setAttribute('y',462);\n  lg.textContent = 'solid = strong path      dashed = weak / login-walled      tap a node to pin it';\n  svg.appendChild(lg);\n\n  // interactions\n  let pinned = null;\n  function focus(id){\n    svg.classList.add('focusing');\n    $$('.node',svg).forEach(el => el.classList.remove('on'));\n    $$('.edge',svg).forEach(el => { el.classList.remove('on'); el.setAttribute('marker-end','url(#arr)'); });\n    if (!id) return;\n    nodeEls[id].classList.add('on');\n    edges.forEach(([from,to]) => {\n      if (from === id || to === id){\n        const e = edgeEls[from+'-'+to];\n        e.classList.add('on');\n        e.setAttribute('marker-end', 'url(#arr-on)');\n        nodeEls[from].classList.add('on');\n        nodeEls[to].classList.add('on');\n      }\n    });\n    const n = byId[id];\n    $('#diagram-info h4').textContent = n.info[0];\n    $('#diagram-info p').textContent = n.info[1];\n  }\n  function clearFocus(){\n    if (pinned){ focus(pinned); return; }\n    svg.classList.remove('focusing');\n    $$('.node.on',svg).forEach(el => el.classList.remove('on'));\n    $$('.edge.on',svg).forEach(el => { el.classList.remove('on'); el.setAttribute('marker-end','url(#arr)'); });\n    $('#diagram-info h4').textContent = '👆 Hover or tap a node';\n    $('#diagram-info p').textContent = 'The diagram shows the path from a user\\u2019s question to a citation of your business. Highlight a node to trace its connections.';\n  }\n  nodes.forEach(n => {\n    nodeEls[n.id].addEventListener('mouseenter', () => focus(n.id));\n    nodeEls[n.id].addEventListener('mouseleave', clearFocus);\n    nodeEls[n.id].addEventListener('click', e => {\n      e.stopPropagation();\n      pinned = (pinned === n.id) ? null : n.id;\n      pinned ? focus(pinned) : clearFocus();\n    });\n  });\n  svg.addEventListener('click', () => { pinned = null; clearFocus(); });\n})();\n\n/* ================= 2. robots.txt bot picker ================= */\n(function botPicker(){\n  const BOTS = [\n    {ua:'GPTBot', op:'OpenAI', role:'Model training', tag:'training', allow:true},\n    {ua:'OAI-SearchBot', op:'OpenAI', role:'ChatGPT search — gets you cited', tag:'citation', allow:true},\n    {ua:'ChatGPT-User', op:'OpenAI', role:'Fetches page on user click', tag:'citation', allow:true},\n    {ua:'ClaudeBot', op:'Anthropic', role:'Model training', tag:'training', allow:true},\n    {ua:'Claude-SearchBot', op:'Anthropic', role:\"Claude's web search\", tag:'citation', allow:true},\n    {ua:'Claude-Web', op:'Anthropic', role:'Claude browsing / fetch', tag:'citation', allow:true},\n    {ua:'PerplexityBot', op:'Perplexity', role:'Indexing for answers', tag:'citation', allow:true},\n    {ua:'Perplexity-User', op:'Perplexity', role:'User-initiated fetch', tag:'citation', allow:true},\n    {ua:'Google-Extended', op:'Google', role:'Gemini training only — no ranking effect', tag:'training', allow:true},\n    {ua:'meta-externalagent', op:'Meta', role:'Meta AI features', tag:'training', allow:true},\n    {ua:'Applebot', op:'Apple', role:'Siri · Spotlight · Apple Intelligence', tag:'citation', allow:true},\n    {ua:'CCBot', op:'Common Crawl', role:'Open dataset many models train on', tag:'training', allow:true},\n    {ua:'Bingbot', op:'Microsoft', role:'Bing index — feeds Copilot & ChatGPT search', tag:'essential', allow:true,\n      note:'Usually already allowed; listed for completeness.'},\n    {ua:'Bytespider', op:'ByteDance', role:'Aggressive scraper', tag:'optional', allow:false,\n      note:'Blocked by default — blocking it does not hurt Western assistants.'},\n  ];\n  const grid = $('#botgrid');\n  grid.innerHTML = BOTS.map((b,i) => `\n    <div class=\"bot ${b.allow ? 'allowed' : 'blocked'}\" data-i=\"${i}\" role=\"checkbox\" aria-checked=\"${b.allow}\" tabindex=\"0\">\n      <span class=\"state\">${b.allow ? '✓ allow' : '⛔ block'}</span>\n      <div class=\"ua\">${esc(b.ua)}</div>\n      <div class=\"role\">${esc(b.op)} · ${esc(b.role)}</div>\n      <span class=\"badge ${b.tag}\">${b.tag}</span>\n      ${b.note ? `<div class=\"bot-note\">${esc(b.note)}</div>` : ''}\n    </div>`).join('');\n\n  function render(){\n    let out = '# Allow AI assistants to crawl and cite this site\\nUser-agent: *\\nAllow: /\\n\\n';\n    let allowed = 0, blocked = 0;\n    BOTS.forEach(b => {\n      if (b.allow){ out += `User-agent: ${b.ua}\\nAllow: /\\n\\n`; allowed++; }\n      else { out += `User-agent: ${b.ua}\\nDisallow: /\\n\\n`; blocked++; }\n    });\n    $('#robots-out code').textContent = out.replace(/\\n+$/,'') + '\\n';\n    $('#bot-summary').textContent = `${allowed} allowed · ${blocked} blocked — paste at https://yoursite.com/robots.txt`;\n  }\n  grid.addEventListener('click', e => {\n    const card = e.target.closest('.bot'); if (!card) return;\n    const b = BOTS[+card.dataset.i];\n    b.allow = !b.allow;\n    card.classList.toggle('allowed', b.allow);\n    card.classList.toggle('blocked', !b.allow);\n    card.setAttribute('aria-checked', b.allow);\n    card.querySelector('.state').textContent = b.allow ? '✓ allow' : '⛔ block';\n    render();\n  });\n  grid.addEventListener('keydown', e => {\n    if ((e.key === 'Enter' || e.key === ' ') && e.target.classList.contains('bot')){\n      e.preventDefault(); e.target.click();\n    }\n  });\n  render();\n})();\n\n/* ================= 3. JSON-LD builder ================= */\n(function schemaBuilder(){\n  const DAYS = [['Monday',1],['Tuesday',1],['Wednesday',1],['Thursday',1],['Friday',1],['Saturday',0],['Sunday',0]];\n  const dayRow = $('#schema-days');\n  dayRow.innerHTML = DAYS.map(([d,on],i) =>\n    `<span class=\"chip ${on ? 'on' : ''}\" data-d=\"${d}\" role=\"checkbox\" aria-checked=\"${!!on}\" tabindex=\"0\">${d.slice(0,3)}</span>`).join('');\n  dayRow.addEventListener('click', e => {\n    const c = e.target.closest('.chip'); if (!c) return;\n    c.classList.toggle('on');\n    c.setAttribute('aria-checked', c.classList.contains('on'));\n    render();\n  });\n  dayRow.addEventListener('keydown', e => {\n    if ((e.key === 'Enter' || e.key === ' ') && e.target.classList.contains('chip')){\n      e.preventDefault(); e.target.click();\n    }\n  });\n\n  const F = ['f-name','f-url','f-phone','f-price','f-street','f-city','f-postal','f-country','f-gbp','f-fb','f-ig','f-img','f-opens','f-closes'];\n  F.forEach(id => $('#'+id).addEventListener('input', render));\n\n  function render(){\n    const v = id => $('#'+id).value.trim();\n    const name = v('f-name'), url = v('f-url');\n    const warn = $('#schema-warn');\n    if (!name || !url){\n      warn.style.display = 'block';\n      warn.textContent = 'Business name and website URL are required — fill those two at minimum.';\n    } else warn.style.display = 'none';\n\n    const o = { '@context':'https://schema.org', '@type':'LocalBusiness', name: name || 'Your Business Name', url: url || 'https://yoursite.com' };\n    if (v('f-img')) o.image = v('f-img');\n    if (v('f-phone')) o.telephone = v('f-phone');\n    if (v('f-price')) o.priceRange = v('f-price');\n    if (v('f-street') || v('f-city') || v('f-postal') || v('f-country')){\n      o.address = { '@type':'PostalAddress' };\n      if (v('f-street')) o.address.streetAddress = v('f-street');\n      if (v('f-city')) o.address.addressLocality = v('f-city');\n      if (v('f-postal')) o.address.postalCode = v('f-postal');\n      if (v('f-country')) o.address.addressCountry = v('f-country');\n    }\n    const sameAs = ['f-gbp','f-fb','f-ig'].map(v).filter(Boolean);\n    if (sameAs.length) o.sameAs = sameAs;\n    const days = $$('.chip.on', dayRow).map(c => c.dataset.d);\n    if (days.length && v('f-opens') && v('f-closes')){\n      o.openingHoursSpecification = [{ '@type':'OpeningHoursSpecification', dayOfWeek: days, opens: v('f-opens'), closes: v('f-closes') }];\n    }\n    $('#schema-out code').textContent = '<' + 'script type=\"application/ld+json\">\\n' + JSON.stringify(o, null, 2) + '\\n<' + '/script>';\n  }\n  render();\n})();\n\n/* ================= 4. quick-start checklist ================= */\n(function checklist(){\n  const ITEMS = [\n    'robots.txt allows the AI bots (section 1 generator)',\n    'Cloudflare / WAF verified: curl -A \"OAI-SearchBot/1.0\" returns 200',\n    'Raw-HTML test passed: key facts visible in curl output, not JS-injected',\n    'LocalBusiness JSON-LD with sameAs added & validated in Rich Results Test',\n    'Site submitted to Google Search Console AND Bing Webmaster Tools (IndexNow)',\n    'Google Business Profile 100% complete',\n    '5 owner-answered Q&As seeded on the Google profile',\n    'Review requests sent to 5 recent customers',\n    'FAQ page live with 10 real customer questions, answer-first style',\n    'llms.txt added (low expectations) + sitemap fresh',\n    'Baseline logged in the prompt tracker: asked 4 assistants the money queries',\n  ];\n  const KEY = 'geoChecklist';\n  let state = store(KEY) || {};\n  const list = $('#quicklist');\n  list.innerHTML = ITEMS.map((t,i) => `\n    <li data-i=\"${i}\" role=\"checkbox\" aria-checked=\"${!!state[i]}\" tabindex=\"0\">\n      <span class=\"box\">✓</span><span class=\"txt\">${esc(t)}</span>\n    </li>`).join('');\n\n  function paint(){\n    const done = ITEMS.reduce((n,_,i) => n + (state[i] ? 1 : 0), 0);\n    const pct = Math.round(done / ITEMS.length * 100);\n    $('#progress-fill').style.width = pct + '%';\n    $('#progress-label').textContent = pct + '%';\n    $$('li',list).forEach(li => {\n      const on = !!state[li.dataset.i];\n      li.classList.toggle('done', on);\n      li.setAttribute('aria-checked', on);\n    });\n  }\n  function toggle(li){\n    const i = li.dataset.i;\n    state[i] = !state[i];\n    store(KEY, state);\n    paint();\n  }\n  list.addEventListener('click', e => { const li = e.target.closest('li'); if (li) toggle(li); });\n  list.addEventListener('keydown', e => {\n    if ((e.key === 'Enter' || e.key === ' ') && e.target.tagName === 'LI'){ e.preventDefault(); toggle(e.target); }\n  });\n  $('#progress-reset').addEventListener('click', () => { state = {}; store(KEY, state); paint(); });\n  paint();\n})();\n\n/* ================= 5. prompt tracker ================= */\n(function promptTracker(){\n  const ASSISTANTS = ['ChatGPT','Claude','Perplexity','Gemini','Copilot'];\n  const KEY = 'geoPrompts';\n  const hits = new Set();\n  const chipRow = $('#pt-chips');\n  chipRow.innerHTML = ASSISTANTS.map(a =>\n    `<span class=\"chip assist\" data-a=\"${a}\" role=\"checkbox\" aria-checked=\"false\" tabindex=\"0\">${a}</span>`).join('');\n  function toggle(c){\n    const a = c.dataset.a;\n    hits.has(a) ? hits.delete(a) : hits.add(a);\n    c.classList.toggle('on');\n    c.setAttribute('aria-checked', c.classList.contains('on'));\n  }\n  chipRow.addEventListener('click', e => { const c = e.target.closest('.chip'); if (c) toggle(c); });\n  chipRow.addEventListener('keydown', e => {\n    if ((e.key === 'Enter' || e.key === ' ') && e.target.classList.contains('chip')){ e.preventDefault(); toggle(e.target); }\n  });\n\n  let entries = store(KEY) || [];\n  function render(){\n    const list = $('#pt-list'), empty = $('#pt-empty');\n    empty.style.display = entries.length ? 'none' : 'block';\n    list.innerHTML = entries.map((en,i) => `\n      <div class=\"pt-entry\">\n        <div>\n          <div class=\"q\">${esc(en.q)}</div>\n          <div class=\"d\">${esc(en.date)}</div>\n          <div class=\"badges\">${ASSISTANTS.map(a =>\n            `<span class=\"pt-b ${en.hits.includes(a) ? 'hit' : ''}\">${a}</span>`).join('')}\n          </div>\n        </div>\n        <button class=\"pt-del\" data-i=\"${i}\" title=\"Delete entry\">✕</button>\n      </div>`).join('');\n  }\n  $('#pt-save').addEventListener('click', () => {\n    const q = $('#pt-query').value.trim();\n    if (!q){ $('#pt-query').focus(); return; }\n    entries.unshift({ q, date: new Date().toISOString().slice(0,10), hits: ASSISTANTS.filter(a => hits.has(a)) });\n    entries = entries.slice(0, 100);\n    store(KEY, entries);\n    $('#pt-query').value = '';\n    hits.clear();\n    $$('.chip', chipRow).forEach(c => { c.classList.remove('on'); c.setAttribute('aria-checked','false'); });\n    render();\n  });\n  $('#pt-query').addEventListener('keydown', e => { if (e.key === 'Enter') $('#pt-save').click(); });\n  $('#pt-list').addEventListener('click', e => {\n    const b = e.target.closest('.pt-del'); if (!b) return;\n    entries.splice(+b.dataset.i, 1);\n    store(KEY, entries);\n    render();\n  });\n  render();\n})();\n</script>\n<script src=\"/session-widget.js\" defer></script>\n</body></html>";
